test('Kontexthinweise funktionieren als Mouseover und antippbares Flyover; Text bleibt sicher und es wird nichts gebucht',()=>{
 const a=app(),w=a.context.window;w.innerWidth=768;w.innerHeight=800;
 const element=()=>({dataset:{},style:{},attributes:{},children:[],textContent:'',setAttribute(k,v){this.attributes[k]=v;},getAttribute(k){return this.attributes[k]??null;},removeAttribute(k){delete this.attributes[k];},hasAttribute(k){return Object.hasOwn(this.attributes,k);},appendChild(x){this.children.push(x);x.parent=this;},remove(){if(this.parent)this.parent.children=this.parent.children.filter(c=>c!==this);},contains(x){return x===this||this.children.includes(x);},getBoundingClientRect(){return {left:20,top:20,right:320,bottom:140,width:300,height:120};}}),parent=element(),button=element();a.context.document.createElement=element;a.context.document.body=parent;button.attributes['data-context-help']='';button.attributes.title='Hinweis';button.dataset={helpShort:'Kurzer Hinweis',helpLong:'Lange Erklärung <img src=x>'};button.closest=s=>s==='dialog[open]'?parent:button;
 a.ui.action('personal-preference',{preference:'help',value:'more'});a.listeners['doc-pointerover']({target:button,pointerType:'mouse'});assert.equal(parent.children.length,1);assert.equal(parent.children[0].attributes.role,'tooltip');assert.equal(parent.children[0].children[0].textContent,'Lange Erklärung <img src=x>');assert.equal(button.attributes['aria-describedby'],'context-hint');a.listeners['doc-pointerout']({target:button,relatedTarget:null});assert.equal(parent.children.length,0);assert.equal(button.attributes.title,'Hinweis');
 a.listeners['doc-pointerover']({target:button,pointerType:'touch'});assert.equal(parent.children.length,0);button.dataset.action='context-help';a.listeners['doc-click']({target:button,preventDefault(){}});assert.equal(parent.children.length,1);assert.equal(parent.children[0].attributes.role,'dialog');assert.equal(button.attributes['aria-expanded'],'true');const before=JSON.stringify(a.ui.state());a.listeners['doc-keydown']({key:'Escape',preventDefault(){}});assert.equal(parent.children.length,0);assert.equal(JSON.stringify(a.ui.state()),before);
 a.ui.action('personal-preference',{preference:'help',value:'less'});a.listeners['doc-click']({target:button,preventDefault(){}});assert.equal(parent.children[0].children[0].textContent,'Kurzer Hinweis');assert.equal(a.ui.state().entries.length,0);a.ui.action('hint-close');assert.equal(parent.children.length,0);
});
