 ui.setState(foundations());ui.setBook({date:'2026-10-20',reference:'Entwurf',text:'Meine Einzahlung',bankGuess:'',balanceGuess:'',lines:[{side:'debit',account:'280',amount:'200'},{side:'credit',account:'288',amount:'200'}]});ui.nav('booking');ui.refreshFocus();const f=nodes.get('focus-accounts-body').innerHTML;assert.ok(f.includes('datetime="2026-10-20"'));assert.ok(f.includes('Meine Einzahlung'));assert.ok(f.includes('<strong>Kasse</strong>'));assert.equal(ui.state().entries.length,0);
