 for(const h of [ui.miniBalanceHTML(p),ui.balanceImpactHTML(p)]){const positions=['data-balance-group="fixed"','data-balance-group="current"','data-balance-group="equity"','data-balance-group="debt"'].map(x=>h.indexOf(x));assert.ok(positions.every((n,i)=>n>=0&&(!i||n>positions[i-1])));assert.match(h,/data-balance-group="fixed">[\s\S]*?<h5>Anlagevermögen<\/h5>[\s\S]*?data-account="084"/);assert.match(h,/data-balance-group="current">[\s\S]*?<h5>Umlaufvermögen<\/h5>[\s\S]*?data-account="280"/);assert.ok(h.includes('<strong>Fuhrpark</strong>'));assert.equal(/vorher|nachher/.test(h),false);assert.ok(h.includes('>+200,00'));assert.ok(h.includes('>−200,00'));assert.ok(h.includes('data-mini-target="084"'));}
 let h=ui.miniBalanceHTML(preview([['280','debit','200'],['300','credit','200']]));assert.match(h,/data-balance-group="equity">[\s\S]*?data-account="300"/);h=ui.miniBalanceHTML(preview([['425','debit','200'],['440','credit','200']]));assert.match(h,/data-balance-group="debt">[\s\S]*?data-account="425"[\s\S]*?data-account="440"/);h=ui.miniBalanceHTML(preview([['670','debit','200'],['280','credit','200']]));assert.match(h,/data-balance-group="equity">[\s\S]*?data-mini-target="EK"/);h=ui.miniBalanceHTML(preview([['290','debit','200'],['670','credit','200']]));assert.ok(h.includes('data-balance-group="ara"'));assert.equal(s.entries.length,0);
