test('Fokusansicht speichert Breite, Seiten und Berichtsanordnung, ohne Buchungen oder Lernfortschritt zu verändern',()=>{
 const a=app();a.ui.setState(foundations());a.ui.setBook({date:'2026-10-16',reference:'Mein Entwurf',text:'Einzahlung',bankGuess:'',balanceGuess:'',lines:[{side:'debit',account:'280',amount:'200,'},{side:'credit',account:'288',amount:''}]});a.ui.nav('booking');a.ui.refreshFocus();const initial=a.ui.state();assert.equal(a.nodes.get('focus-window-income').hidden,false);assert.ok(a.nodes.get('focus-income-body').innerHTML.includes('Keine Erfolgswirkung'));
 a.ui.action('focus-swap');a.ui.action('focus-report-order');a.ui.action('focus-report-layout');a.listeners['doc-input']({target:{id:'focus-size',value:'62'}});a.listeners['doc-change']({target:{id:'focus-size',value:'62'}});assert.equal(a.nodes.get('focus-layout').getAttribute('data-book-side'),'right');assert.equal(a.nodes.get('focus-layout').style['--focus-left'],'38fr');assert.equal(a.nodes.get('focus-reports').getAttribute('data-first'),'income');assert.equal(a.nodes.get('focus-reports').getAttribute('data-stacked'),'true');assert.deepEqual(a.ui.state().drafts.focus,[62,1,1,1,6]);assert.deepEqual(a.ui.state().entries,initial.entries);assert.deepEqual(a.ui.state().learning,initial.learning);assert.equal(a.ui.state().drafts.book.lines[0].amount,'200,');
 const b=app({local:a.local});b.ui.refreshFocus();assert.equal(b.nodes.get('focus-layout').getAttribute('data-book-side'),'right');assert.equal(b.nodes.get('focus-size').value,'62');assert.equal(b.nodes.get('focus-window-income').hidden,false);assert.equal(b.ui.state().drafts.book.reference,'Mein Entwurf');b.ui.action('focus-layout-reset');assert.equal(b.nodes.get('focus-size').value,'50');assert.equal(b.nodes.get('focus-layout').getAttribute('data-book-side'),'left');assert.equal(b.nodes.get('focus-reports').getAttribute('data-first'),'balance');assert.equal(b.ui.state().drafts.focus,undefined);assert.equal(b.ui.state().entries.length,0);b.context.window.matchMedia=()=>({matches:true});b.listeners.resize();assert.equal(b.nodes.get('focus-size').disabled,true);assert.equal(b.nodes.get('focus-swap').textContent,'Veränderungen zuerst');assert.equal(b.nodes.get('focus-size-label').textContent,'Breite im Querformat');
 const D=a.context.BioCasaDrafts;for(const bad of [[99,0,0,0,6],[50,2,0,0,6],[50,0,0,0,8],[50,0,0,0,'6'],[50,0,0,0]])assert.throws(()=>D.validate({focus:bad}),/Ungültige/);
});
test('Trenner unterstützt Pointer, Touch-Abbruch und Tastatur; Größenänderung hält die Buchungsmaske bestehen',()=>{
 const a=app();a.ui.setState(foundations());a.ui.nav('booking');a.ui.refreshFocus();const layout=a.nodes.get('focus-layout'),handle=a.nodes.get('focus-divider');layout.getBoundingClientRect=()=>({left:100,width:1000});let captured=null;handle.setPointerCapture=id=>{captured=id;};handle.releasePointerCapture=()=>{captured=null;};const down=()=>a.listeners['doc-pointerdown']({target:{closest:()=>handle},pointerId:7,button:0,preventDefault(){}}),move=x=>a.listeners['doc-pointermove']({pointerId:7,clientX:x,preventDefault(){}});const mask=a.nodes.get('booking-focus-content').innerHTML;
 down();assert.equal(captured,7);move(900);assert.equal(a.nodes.get('focus-size').value,'65');a.listeners['doc-pointerup']({pointerId:7});assert.equal(captured,null);assert.equal(a.ui.state().drafts.focus[0],65);assert.equal(a.nodes.get('booking-focus-content').innerHTML,mask);
 down();move(100);assert.equal(a.nodes.get('focus-size').value,'35');a.listeners['doc-pointercancel']({pointerId:7});assert.equal(a.nodes.get('focus-size').value,'65');assert.equal(a.ui.state().drafts.focus[0],65);
 a.ui.action('focus-swap');a.listeners['doc-keydown']({target:{id:'focus-divider'},key:'ArrowRight',preventDefault(){}});assert.equal(a.nodes.get('focus-size').value,'63');a.listeners['doc-keydown']({target:{id:'focus-divider'},key:'Home',preventDefault(){}});a.runTimers();assert.equal(a.ui.state().drafts.focus[0],35);assert.equal(a.ui.state().entries.length,0);
});
