// A measured miniature host, connected to the actual application event handlers.
// It exercises animation scheduling and the input/change boundary without a browser.
function miniDOM(a,html){
 const decode=s=>s.replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&');
 const element=()=>({dataset:{},style:{},children:[],isConnected:true,hidden:false,textContent:'',classList:{v:new Set(),add(...xs){xs.forEach(x=>this.v.add(x));},remove(...xs){xs.forEach(x=>this.v.delete(x));}},setAttribute(k,v){this[k]=v;},focus(){},scrollIntoView(){},getBoundingClientRect:()=>({left:0,top:0,bottom:80,width:350,height:600}),appendChild(x){this.children.push(x);x.parent=this;},remove(){if(this.parent)this.parent.children=this.parent.children.filter(x=>x!==this);},animate(){return {cancel(){},pause(){},play(){}};}});
 const doc=a.context.document;doc.createElement=element;doc.createElementNS=element;
 const host=element(),play=element(),status=element(),sources=[...html.matchAll(/data-target-account="([^"]+)" data-amount-text="([^"]*)" data-flow-label="([^"]*)"/g)].map(m=>Object.assign(element(),{dataset:{targetAccount:m[1],amountText:decode(m[2]),flowLabel:decode(m[3])}})),targets=[...html.matchAll(/data-mini-target="([^"]+)"/g)].map(m=>Object.assign(element(),{dataset:{miniTarget:m[1]}}));
 const feedback=element(),count=element(),steps=Array.from({length:4},()=>({hidden:true,querySelector:()=>element()})),box=element();let selected=[];
 const context=html.match(/data-check-context="([^"]*)"/);box.dataset={checkContext:context?decode(context[1]):'',checkIndex:'0'};box.hidden=true;box.querySelector=s=>s==='[data-check-feedback]'?feedback:s==='[data-check-count]'?count:steps[Number(s.match(/step="(\d)"/)?.[1])];box.querySelectorAll=()=>selected;
 host.ownerDocument=doc;host.dataset.miniSignature=decode(html.match(/data-mini-signature="([^"]*)"/)[1]);host.querySelector=s=>s==='[data-mini-play]'?play:s==='[data-mini-status]'?status:s==='[data-mini-check]'?(context?box:null):targets.find(t=>s==='[data-mini-target="'+t.dataset.miniTarget+'"]')||null;host.querySelectorAll=s=>s==='[data-mini-flow]'?sources:s==='[data-mini-target]'?targets:[...sources,...targets];
 return {host,box,feedback,select(q,value='0'){selected=[...selected.filter(e=>e.dataset.checkQuestion!==q),{dataset:{checkQuestion:q},value}];}};
}
