 const parts=new Map(),part=s=>{if(!parts.has(s))parts.set(s,{textContent:'',disabled:true});return parts.get(s);},host={open:false,style:{},querySelector:part,showModal(){this.open=true;},close(){this.open=false;},getBoundingClientRect:()=>({left:0,top:0,right:300,bottom:580,width:300,height:580})},form={querySelector:()=>host};let inputs=0,changes=0,returned=false;const input={value:'',isConnected:true,closest:()=>form,dispatchEvent(e){if(e.type==='input')inputs++;else if(e.type==='change')changes++;},focus(){}},field={querySelector:()=>input};a.context.window.Event=class{constructor(type){this.type=type;}};a.context.window.innerWidth=768;a.context.window.innerHeight=1024;
 const el={dataset:{label:'Dein Saldo'},closest:s=>s==='[data-sum-field]'?field:host,getBoundingClientRect:()=>({left:650,right:698,top:750,bottom:798}),focus(){returned=true;}};a.ui.openCalculator(el);assert.equal(host.open,true);assert.equal(host.style.left,'340px');assert.equal(host.style.top,'160px');assert.ok(part('[data-sum-target]').textContent.includes('Dein Saldo'));for(const key of ['2','0','0','-','5','0','equals'])a.ui.useCalculator({dataset:{key},closest:()=>host});assert.equal(input.value,'');assert.equal(part('[data-action="sum-accept"]').disabled,false);a.ui.acceptCalculator({closest:()=>host});assert.equal(input.value,'150,00');assert.equal(inputs,1);assert.equal(changes,1);assert.equal(host.open,false);assert.equal(a.ui.state().entries.length,0);
 a.ui.openCalculator(el);let prevented=false;a.listeners['doc-cancel']({target:host,preventDefault(){prevented=true;}});assert.equal(prevented,true);assert.equal(host.open,false);assert.equal(returned,true);assert.equal(input.value,'150,00');
