 a.ui.openCalculator(button);let capture=null;const grip={closest:s=>s==='[data-sum-grip]'?grip:host,focus(){},setPointerCapture:id=>{capture=id;},hasPointerCapture:id=>capture===id,releasePointerCapture:()=>{capture=null;}};
